  'profile.upload_mode_stake_desc1': { zh: '• 进入「听审竞技场」竞逐 30 票 Upvote 挑战', en: '• Enter Curation Arena, compete for 30 Upvote challenge', ja: '• キュレーションアリーナに参加、30 Upvoteに挑戦' },
  'profile.upload_mode_stake_desc2': { zh: '• 🏆 挑战成功：登上首页推荐榜，退回质押积分！', en: '• 🏆 Win: Featured on homepage & stake refunded!', ja: '• 🏆 成功：ホームページ掲載＆ステーク返金！' },
  'profile.upload_mode_stake_desc3': { zh: '• 🔽 挑战失败：质押不退，作品保留为普通', en: '• 🔽 Lose: Stake forfeited, song listed normally', ja: '• 🔽 失敗：ステーク没収、曲は通常掲載' },
