  'profile.upload_mode_stake_fail_desc': { zh: '质押不退并作为伯乐分红，作品保留为普通', en: 'stake forfeited and distributed as Curation dividends, work listed normally', ja: 'ステークは没収され、キュレーターに分配されます。作品は通常掲載として残ります' },
  'profile.upload_mode_stake_amount': { zh: '质押数量', en: 'Stake Amount', ja: 'ステーク数量' },
