  'profile.upload_ipo_shares_label': { zh: '发行总份额 (1 ECHO = 1 份)', en: 'Total Shares (1 ECHO = 1 share)', ja: '総発行数 (1 ECHO = 1シェア)' },
  'profile.upload_ipo_sell_ratio': { zh: '权益出售比例', en: 'Equity Sale Ratio', ja: '権益売却比率' },
