  'profile.mission_architecture': { zh: '使命愿景与架构公示', en: 'Platform Vision & Architecture', ja: 'ミッション・ビジョン及びアーキテクチャ公開' },
  'profile.social_rewards_title': { zh: '专属社交裂变奖励', en: 'Exclusive Social Referral Rewards', ja: '紹介リワード特典' },
  'profile.social_rewards_desc': { zh: '分享您的专属邀请码给好友，好友在注册时填写此码。注册成功后，新成员可得 10 ECHO 新人礼包，您将获得 5.00 ECHO 邀请人分润奖励，秒级发放到账！', en: 'Share your invite code with friends. Once registered with your code, they get 10 ECHO as a welcome gift, and you earn a 5.00 ECHO referral reward in real-time!', ja: '紹介コードを友達と共有しましょう。友達がコードを使って登録すると、ウェルカムギフトとして10 ECHOを獲得し、あなたにはリアルタイムで5.00 ECHOの紹介報酬が支払われます！' },
